void fn0() {

  List<String> wordBreak = ['leet', 'code'];
  String sentence = "leetcode";
  Set<String> dictionary = wordBreak.toSet();

  bool canSegment = false;
  int minWords = 0;
  List<String> segmentations = [];

  void backtrack(int index, List<String> current, List<bool> used, List<String> segmentations, int minWords) {
    if (index == sentence.length) {
      segmentations.add(current.join(' '));
      return;
    }

    for (String word in dictionary) {
      int len = word.length;
      if (index + len > sentence.length) continue;
      bool match = true;
      for (int i = 0; i < len; i++) {
        if (sentence[index + i] != word[i]) {
          match = false;
          break;
        }
      }
      if (!match) continue;

      List<bool> newUsed = List<bool>.from(used);
      for (int i = 0; i < len; i++) {
        newUsed[index + i] = true;
      }
      current.add(word);
      backtrack(index + len, current, newUsed, segmentations, minWords);
      current.removeLast();
    }
  }

  bool memoized = false;
  if (memoized) {

    Map<String, List<List<bool>>> memo = {};
    Map<String, int> wordIdx = {};

    for (int i = 0; i < dictionary.length; i++) {
      wordIdx[dictionary[i]] = i;
    }

    void dfs(int index, List<bool> used, List<String> segmentations) {
      if (index == sentence.length) {
        segmentations.add(sentence);
        return;
      }

      if (memo.containsKey(sentence.substring(index))) {
        List<List<bool>> cached = memo[sentence.substring(index)]!;
        for (List<bool> seg in cached) {
          if (seg.isNotEmpty) {
            segmentations.add(sentence.substring(index, index + seg.length));
          }
        }
        return;
      }

      List<bool> options = List<bool>.filled(2, false);
      for (int i = 0; i < dictionary.length; i++) {
        if (dictionary[i].length <= sentence.length - index) {
          String sub = sentence.substring(index, index + dictionary[i].length);
          bool isPrefix = true;
          for (int j = 0; j < dictionary[i].length; j++) {
            if (sub[j] != dictionary[i][j]) {
              isPrefix = false;
              break;
            }
          }
          if (isPrefix) {
            options[0] = true;
            break;
          }
        }
      }

      if (options[0]) {

        List<bool> newUsed = List<bool>.from(used);
        for (int i = 0; i < dictionary.length; i++) {
          newUsed[i] = true;
        }
        dfs(index + dictionary.length, newUsed, segmentations);
      }

      options[1] = true;
      dfs(index + 1, used, segmentations);
    }

    dfs(0, List<bool>.filled(dictionary.length, false), []);
  } else {
    backtrack(0, [], [], [], -1);
  }

  if (segmentations.isEmpty) {
    print('Cannot segment');
  } else if (segmentations.length == 1) {
    print('Can segment: ${segmentations[0]}');
  } else {
    print('All possible segmentations: $segmentations');
  }

  if (segmentations.isNotEmpty) {
    if (segmentations.length > 1) {
      print('Minimum words needed: ${segmentations.length - 1}');
    } else {
      print('Minimum words needed: 0');
    }
  }

  print('String: "$sentence", Dictionary: ${dictionary.toSet()}');
  print('=== Word Break (Can Segment?) ===');
  print('================================');

  if (memoized) {
    print('=== Word Break II (All Segmentations) ===');
    print('====================================');
  } else {
    print('=== Minimum Word Breaks ===');
    print('=========================');
  }
}

