      n += value;
      history.last.add(value);
      stack.add(value);
    }
  }
  int total = n;
  List<int> sorted = List<int>.of(stack)..sort();
  return {'total': total, 'added': n - sorted.isEmpty ? 0 : sorted.last, 'history': history};
}

