        int next = stack.removeLast();
        stack[stack.length - 1] = next + below;
      }
    } else if (cmd == 'UNDO') {
      if (stack.length > 1) {
        int removed = stack.removeLast();
        int next = stack.removeLast();
        stack[stack.length - 1] = next - removed;
      }
      counts['UNDO'] = counts['UNDO']! + 1;
    }
  }

  for (String cmd in commands) {
    executeCommand(cmd);
  }

  return counts;
}

