  HERE IS A SIMPLE EXAMPLE

  The function takes two arguments:
  1. A string representing the text in which the pattern is searched.
  2. A string representing the pattern that is searched for.

  The function returns an array containing the indices at which the pattern is found.
  If the pattern is not found, the array is empty.

  The main function demonstrates the use of the binary search function.
  It searches for the string "EXAMPLE" in the string "HERE IS A SIMPLE EXAMPLE".
  The search is case-insensitive.
  ''';

  String pattern = "EXAMPLE";

  List<int> binarySearch(String text, String pattern) {
    List<int> result = [];

    if (pattern.isEmpty) {
      return result;
    }

    List<String> words = text.split(' ');

    int left = 0;
    int right = words.length - 1;
    int firstIdx = -1;

    while (left <= right) {
      int mid = left + (right - left) ~/ 2; 

      String word = words[mid];

      int len = word.length;
      int subLen = pattern.length;

      if (len == subLen) {
        if (word == pattern) {
          firstIdx = mid;
          right = mid - 1;
        } else if (word.compareTo(pattern) < 0) {
          left = mid + 1;
        } else {
          right = mid - 1;
        }
      } else if (len < subLen) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }

    if (firstIdx == -1) {
      return result;
    }

    for (int i = firstIdx; i < words.length; i++) {
      String word = words[i];
      if (word.length != pattern.length) {
        continue;
      }
      bool isMatch = true;
      for (int j = 0; j < pattern.length; j++) {
        if (word[j] != pattern[j]) {
          isMatch = false;
          break;
        }
      }
      if (isMatch) {
        result.add(i);
      }
    }

    return result;
  }

  List<int> searchResults = binarySearch(text, pattern);

  if (searchResults.isEmpty) {
    print("Pattern not found.");
  } else {
    print("Pattern found at positions: ${searchResults.join(', ')}");
  }
}

