String fn0(List<int> xCoords, List<int> yCoords, int maxDist) {
  final n = xCoords.length;
  if (n == 0) return "0:0";

  List<List<int>> dist = List.generate(
    n,
    (_) => List.filled(n, maxDist + 1),
  );

  for (int i = 0; i < n; i++) {
    for (int j = i; j < n; j++) {
      final d = (xCoords[i] - xCoords[j]).abs() +
          (yCoords[i] - yCoords[j]).abs();
      if (d <= maxDist) {
        dist[i][j] = d;
      }
    }
  }

  int minX = xCoords[0], maxX = xCoords[0];
  int minY = yCoords[0], maxY = yCoords[0];
  for (int i = 1; i < n; i++) {
    if (xCoords[i] < minX) minX = xCoords[i];
    if (xCoords[i] > maxX) maxX = xCoords[i];
    if (yCoords[i] < minY) minY = yCoords[i];
    if (yCoords[i] > maxY) maxY = yCoords[i];
  }

  int totalArea = (maxX - minX) * (maxY - minY);
  if (totalArea == 0) return "0:0";

  int covered = 0;
  for (int i = 0; i < n; i++) {
    for (int j = i; j < n; j++) {
      if (dist[i][j] <= maxDist) {
        covered += (xCoords[i] - xCoords[j]).abs() *
            (yCoords[i] - yCoords[j]).abs();
      }
    }
  }

  int areaPerUnit = covered / totalArea;
  int centerX = (minX + maxX) ~/ 2;
  int centerY = (minY + maxY) ~/ 2;
  int cx1 = centerX + maxDist + 1;
  int cy1 = centerY + maxDist + 1;
  int cx2 = centerX - maxDist - 1;
  int cy2 = centerY - maxDist - 1;

  int count = 0;
  for (int i = cx1; i >= minX; i--) {
    for (int j = cy1; j >= minY; j--) {
      bool ok = true;
      for (int k = 0; k < n; k++) {
        if (dist[k][i] <= maxDist && dist[k][j] <= maxDist) {
          ok = false;
          break;
        }
      }
      if (ok) count++;
    }
  }
  for (int i = cx2; i <= maxX; i--) {
    for (int j = cy2; j <= maxY; j--) {
      bool ok = true;
      for (int k = 0; k < n; k++) {
        if (dist[k][i] <= maxDist && dist[k][j] <= maxDist) {
          ok = false;
          break;
        }
      }
      if (ok) count++;
    }
  }

  return "$count:$areaPerUnit";
}

