      if (gap >= 0 && gap <= maxGap) {
        right++;
      } else {
        break;
      }
    }
    if (right == left) {
      right = left + 1;
    } else {
      int currentLen = right - left;
      if (currentLen > bestLen) {
        bestLen = currentLen;
        bestStart = left;
      }
      left = right;
    }
  }
  return bestStart;
}

