int fn0(List<int> quantities, int scaleFactor) {
  if (quantities.isEmpty || scaleFactor == 0) return -1;
  int total = 0;
  for (int q in quantities) {
    total += q;
  }
  int low = 0;
  int high = quantities.length - 1;
  while (low <= high) {
    int mid = low + ((high - low) >> 1);
    int sum = 0;
    for (int i = 0; i <= mid; i++) {
      sum += quantities[i];
    }
    if (sum * scaleFactor > total) {
