void fn0() {

  final rand = Random(0);

  const int cols = 24; 
  const int rows = 10; 
  const double low = 0.33;
  const double medium = 0.66;
  const double high = 1.0;


  List<List<double>> grid = List.generate(
    rows,
    (_) => List.filled(cols, 0),
  );

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (c == 0 || c == cols - 1) {
        grid[r][c] = low;
      } else if (r == 0 || r == rows - 1) {
        grid[r][c] = medium;
      } else {
        grid[r][c] = high;
      }
    }
  }

  int total = rows * cols;
  List<int> indices = List.generate(total, (i) => i);

  indices.shuffle(rand);

  List<List<int>> heatMap = indices
      .expand<int>((_) => grid)
      .toList()
      .expand<int>((_) => grid);

  String legend = '''
  . = low
  * = medium
  # = high
  ''';

  print('User Activity Heatmap (Day x Hour)');
  print('------------------------------------');
  print('Legend:');
  print('${legend.padRight(80)}');
  print('');

  for (int r = 0; r < rows; r++) {
    String rowStr = '';
    for (int c = 0; c < cols; c++) {
      double val = heatMap[r * cols + c];
      String marker = switch (val) {
        < low => '.'.padRight(3),
        <= medium => '*'.padRight(3),
        < high => '#'.padRight(3),
        _ => ' '.padRight(3),
      };
      rowStr += marker;
    }
    print(rowStr);
  }
}

