  List<String> weights = [];
  List<int> quantities = [];
  List<String> ports = [];

  if (manifest.isEmpty) {
    return codes;
  }

  List<String> entries = manifest.split(',');

  Set<String> seenCodes = {};
  Set<String> seenPorts = {};

  for (String entry in entries) {
    List<String> parts = entry.split(':');
    if (parts.length != 4) {
      continue;
    }

    String code = parts[0];
    String port = parts[2];
    int quantity = int.parse(parts[3]);

    if (!seenCodes.contains(code)) {
      seenCodes.add(code);
      codes.add(code);
    }

    if (!seenPorts.contains(port)) {
      seenPorts.add(port);
      ports.add(port);
    }

    weights.add(quantity * int.parse(code));
    quantities.add(quantity);
  }

  if (codes.isEmpty) {
    return codes;
  }

  List<int> indices = List.generate(codes.length, (i) => i);

  indices.sort((int a, int b) {
    if (weights[a] != weights[b]) {
      return weights[b].compareTo(weights[a]);
    }

    if (quantities[a] != quantities[b]) {
      return quantities[a].compareTo(quantities[b]);
    }

    return codes[a].compareTo(codes[b]);
  });

  List<String> result = [];
  for (int i = 0; i < indices.length; i++) {
    result.add(codes[indices[i]]);
  }

  return result;
}

