  const int cols = n;
  const int rows = n;

  final board = List.generate(rows, (_) => List.filled(cols, 0));

  var solutions = 0;
  var solver = QueenSolver(board);

  while (true) {

    final solved = solver.solve(0);
    if (solved) {
      print('Solution $solutions');
      for (int r = 0; r < rows; r++) {
        String rowStr = '';
        for (int c = 0; c < cols; c++) {
          rowStr += board[r][c] == 1 ? 'Q ' : ' . ';
        }
