class QueenSolver {
  final board;
  int row = 0;

  QueenSolver(this.board);

  bool solve(int col) {

    if (col == cols) {
      return true;
    }

    for (int r = 0; r < rows; r++) {
      if (board[r][col] == 1) {
        continue;
      }
      int steps = 0;
      bool safe = true;
      for (int c = 0; c < col; c++) {
        if (board[r][c] == 1) {
          steps++;
        }
      }
      if (steps == 0) {

        board[r][col] = 1;
        if (solve(col + 1)) {
          return true;
        }

        board[r][col] = 0;
      }
    }
    return false;
  }

  void backtrack() {
    while (row < rows && board[row][col] != 0) {
      row++;
    }
    if (row == rows) {
      return;
    }

    for (int c = 0; c < cols; c++) {
      if (board[row][c] == 0) {

        board[row][c] = 1;
        if (solve(c + 1)) {
          return;
        }

        board[row][c] = 0;
      }
    }
  }
}

