void fn0(List<String> args) {

  int n;
  if (args.length < 1) {
    n = 8; 
  } else {
    n = int.parse(args[0]);
    if (n < 1) {
      print('N must be a positive integer.');
      return;
    }
  }

  final List<List<int>> positions = List.generate(n, (_) => List<int>.filled(n, 0));

  bool isSafe(int row, int col) {

    for (int r = 0; r < row; r++) {
      int colR = positions[r][col];
      if (colR == 1) return false; 
    }

    for (int r = row - 1; r >= 0; r--) {
      int colR = positions[r][col];
      if (colR == 1) return false; 
    }

    int diagR = row - 1, diagC = col - 1;
    while (diagR >= 0 && diagC >= 0) {
      int cell = positions[diagR][diagC];
      if (cell == 1) return false; 
      diagR--;
      diagC--;
    }

    int diagR2 = row - 1, diagC2 = col + 1;
    while (diagR2 >= 0 && diagC2 < n) {
      int cell = positions[diagR2][diagC2];
      if (cell == 1) return false; 
      diagR2--;
      diagC2++;
    }

    return true;
  }

  bool solve(int row) {
    if (row == n) {
      return true; 
    }

    for (int col = 0; col < n; col++) {
      if (isSafe(row, col)) {
        positions[row][col] = 1;

        if (solve(row + 1)) {
          return true;
        }

        positions[row][col] = 0;
      }
    }

    return false;
  }

  if (solve(0)) {

    print('Solving N-Queens for N=$n');
    print('Total solutions: ${positions.length}');

    for (int sol = 0; sol < positions.length; sol++) {

      String boardString = '';
      for (int r = 0; r < n; r++) {
        String row = '';
        for (int c = 0; c < n; c++) {
          if (positions[r][c] == 1) {
            row += 'Q ';
          } else {
            row += '. ';
          }
        }
        boardString += row + '\n';
      }

      print('Solution $sol');
      print(boardString);
    }
  } else {
    print('No solution exists for N=$n.');
  }
}

