void solve(int n) {

  final List<bool> cols = List.filled(n, false);
  final int solutions = <String>[];

  void place(int row) {
    if (row == n) {
      solutions.add(cols.map((c) => c ? 'Q' : '.').join(' '));
      return;
    }
    for (int col = 0; col < n; col++) {
      if (!cols[col]) {
        bool safe = true;
        for (int i = 0; i < row; i++) {
          int qCol = cols[i];
          if (qCol == col ||
              (i - row).abs() == (qCol - col).abs()) {
            safe = false;
            break;
          }
        }
        if (safe) {
          cols[col] = true;
          place(row + 1);
          cols[col] = false;
        }
      }
    }
  }

  place(0);

  String totalSolutions = '';
  if (solutions.isEmpty) {
    totalSolutions = 'No solutions found.';
  } else {
    totalSolutions = 'Total solutions: ${solutions.length}';
  }

  print(totalSolutions);

  int solutionIndex = 0;
  for (final String solution in solutions) {
    print('Solution ${solutionIndex + 1}:');
    print(solution);
    solutionIndex++;
  }
}

