      }

      int gap = nextStart - idx;
      if (gap > 0) {
        mashupDuration += songDurations[idx] * gap;
      }

      backtrack(idx + 1, minutesLeft);
    }
  }

  backtrack(start, targetMinutes);
  return {'pairCount': pairCount, 'mashupDuration': mashupDuration};
}

