class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  const Quaternion.unit() : this(1.0, 1.0, 1.0, 1.0);

  const Quaternion.one() : this(1.0, 1.0, 1.0, 1.0);

  const Quaternion.fromList(List<double> list)
      : x = list[0],
        y = list[1],
        z = list[2],
        w = list[3];

  double norm() => sqrt(x * x + y * y + z * z + w * w);

  double conjugate() => x * x - y * y - z * z + w * w;

  Quaternion inverse() =>
      Quaternion(x * x + y * y + z * z + w * w, -x * y - z * w, -x * z - y * w, -w * x - y * z);

  Quaternion normalize() =>
      if (norm() == 0.0) {
        const Quaternion.zero();
      } else {
        final double inv = 1 / norm();
        const Quaternion(x * inv, y * inv, z * inv, w * inv);
      };

  Quaternion operator+(const other) =>
      const Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator-(const other) =>
      const Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator*(const other) =>
      const Quaternion(x * other.x - y * other.y - z * other.z + w * other.w,
          x * other.y + y * other.x + z * other.w - w * other.z,
          x * other.z + y * w + z * other.x - w * other.y,
          x * other.w + y * z - z * other.x + w * other.y);

  Quaternion operator*(double scalar) =>
      const Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  const Quaternion operator^(int power) =>
      power > 0
          ? (power % 2 == 0)
              ? normalize()
              : inverse()
          : const Quaternion.one();

  @override
  String toString() {
    String parts = '$x + $y i + $z j + $w k';
    if (w.abs() >= 2.0) {
      parts += ' ≈ ' +
          (w < 0
              ? '($x + $y i + $z j - 1)/2'
              : '(($x + $y i + $z j + 1)/2)';
    }
    return parts;
  }
}

