    double x = axis[0], y = axis[1], z = axis[2];
    double cosHalf = 0.5 * (1.0 + cos(angle));
    double sinHalf = 0.5 * (1.0 - sin(angle));
    return Quaternion(2 * sinHalf * x, 2 * sinHalf * y, 2 * sinHalf * z, cosHalf);
  }

  static Quaternion fromAxisAngleRad(List<double> axis, double angle) {
    return fromAxisAngle(axis, angle * 180 / pi);
  }

  @override
  String toString() {
