    final sin = sin(angle / 2);
    final cos = cos(angle / 2);
    return Quaternion(cos, sin * x, sin * y, sin * z);
  }

  const Quaternion.fromRotationMatrix(List<double> m) {
    final w = m[0] * m[0] + m[1] * m[1] + m[2] * m[2] + m[3] * m[3];
    final x = m[0] * m[1] - m[2] * m[3];
    final y = m[0] * m[3] + m[2] * m[1];
    final z = m[1] * m[2] - m[0] * m[3];
    return Quaternion(w, x, y, z);
  }

  const Quaternion.fromQuaternionString(String s) {
    final parts = s.split(',');
    double w = double.parse(parts[0]);
    double x = double.parse(parts[1]);
    double y = double.parse(parts[2]);
    double z = double.parse(parts[3]);
    return Quaternion(w, x, y, z);
