  const Quaternion.fromRotationMatrixString(String s) {
    final parts = s.split(',');
    double m00 = double.parse(parts[0]);
    double m01 = double.parse(parts[1]);
    double m02 = double.parse(parts[2]);
    double m03 = double.parse(parts[3]);
    double m10 = double.parse(parts[4]);
    double m11 = double.parse(parts[5]);
    double m12 = double.parse(parts[6]);
    double m13 = double.parse(parts[7]);
    double m20 = double.parse(parts[8]);
    double m21 = double.parse(parts[9]);
    double m22 = double.parse(parts[10]);
    double m23 = double.parse(parts[11]);
    double m30 = double.parse(parts[12]);
    double m31 = double.parse(parts[13]);
    double m32 = double.parse(parts[14]);
