    final sinX = sin(pitch / 2);
    final sinY = sin(roll / 2);
    final sinZ = sin(yaw / 2);
    return Quaternion(
      cos(pitch / 2) * cos(roll / 2) * cos(yaw / 2) + sinX * sinY * sinZ,
      sin(pitch / 2) * cos(roll / 2) * cos(yaw / 2) - cosX * sinY * sinZ,
      cos(pitch / 2) * sin(roll / 2) * cos(yaw / 2) + sinX * cosY * sinZ,
      cos(pitch / 2) * cos(roll / 2) * sin(yaw / 2) - sinX * sinY * cosZ,
    );
