  const Quaternion.fromEulerString(String params) {
    final parts = params.split(',');
    double pitch = double.parse(parts[0]);
    double roll = double.parse(parts[1]);
    double yaw = double.parse(parts[2]);
    return Quaternion.fromEuler(pitch, roll, yaw);
  }

  const Quaternion operator +(const Quaternion other) {
    return Quaternion(
      w + other.w,
      x + other.x,
      y + other.y,
      z + other.z,
    );
  }

  const Quaternion operator -(const Quaternion other) {
    return Quaternion(w - other.w, x - other.x, y - other.y, z - other.z);
  }

  const Quaternion operator *(const Quaternion other) {
    double w = (w * other.w - x * other.x - y * other.y - z * other.z);
    double x = (w * other.x + x * other.w + y * other.z - z * other.y);
    double y = (w * other.y + x * other.z + y * other.w - z * other.x);
    double z = (w * other.z + y * other.x + z * other.y - x * other.w);
