  const Quaternion operator *(double scalar) {
    return Quaternion(
      w * scalar,
      x * scalar,
      y * scalar,
      z * scalar,
    );
  }

  const Quaternion inverse() {
    final inv = 1 / w;
    return Quaternion(inv * w, inv * x, inv * y, inv * z);
  }

  const Quaternion conjugate() {
    return Quaternion(w, x, y, -z);
  }

  const Quaternion normalized() {
    final norm = w * w + x * x + y * y + z * z;
    return Quaternion(w / norm, x / norm, y / norm, z / norm);
  }

  const Quaternion operator ^(int exponent) {
    if (exponent == 0) return Quaternion.identity();
    if (exponent % 2 == 1) return Quaternion.fromList(List.filled(4, w * (1 << exponent)));
