      w * other.w - x * other.x - y * other.y - z * other.z,
      x * other.w + w * x.other - y * other.z + z * other.y,
      y * other.w + x * other.y - w * x.other + z * other.z,
      z * other.w + y * other.z - x * other.y - w * x.other,
    );
  }

  const Quaternion operator ||(const Quaternion other) {
    return Quaternion(
      w * other.w + x * other.x + y * other.y + z * other.z,
      x * other.w - w * x.other + y * other.z - z * other.y,
      y * other.w - x * other.y + w * x.other + z * other.z,
      z * other.w - y * other.z + x * other.y - w * x.other,
    );
  }

  const Quaternion operator %(const Quaternion other) {
    return Quaternion(
      w * other.w - x * other.x - y * other.y - z * other.z,
      x * other.w + w * x.other - y * other.z + z * other.y,
      y * other.w + x * other.y - w * x.other + z * other.z,
      z * other.w - y * other.z + x * other.y - w * x.other,
    );
  }

  @override
  String toString() {
    final parts = <String>[];
    parts.add('${w.toStringAsFixed(2)} + $x.toStringAsFixed(2) * i + $y.toStringAsFixed(2) * j + $z.toStringAsFixed(2) * k);
