class Quaternion {
  final double x, y, z, w; 
  final double norm; 

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);
  const Quaternion.unit() : this(1.0, 1.0, 1.0, 1.0);
  const Quaternion.unitZ() : this(0.0, 0.0, 0.0, 1.0);

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.fromAxisAngle(List<double> axis, double angle) {
    double sx = axis[0], sy = axis[1], sz = axis[2];
    double cosHalf = cos(angle / 2);
    double sinHalf = sin(angle / 2);
    return Quaternion(
      2 * cosHalf * sx + sinHalf * sy * sz,
      2 * cosHalf * sy + sinHalf * sx * sz,
      2 * cosHalf * sz + sinHalf * sx * sy,
      cosHalf * cosHalf - sinHalf * sinHalf,
    );
  }

  const Quaternion.fromAxisAngleComplex(List<double> axis, double angle) {
    double sx = axis[0], sy = axis[1], sz = axis[2];
    double cosHalf = cos(angle / 2);
    double sinHalf = sin(angle / 2);
    return Quaternion(
      2 * cosHalf * sx + sinHalf * sy * sz + sinHalf * sx * sz * sinHalf,
      2 * cosHalf * sy + sinHalf * sx * sz + sinHalf * sy * sx * sinHalf,
      2 * cosHalf * sz + sinHalf * sx * sy + sinHalf * sz * sx * sinHalf,
      cosHalf * cosHalf - sinHalf * sinHalf,
    );
  }

  @override
  String toString() => '$x + $y*i + $z*j + $w*k';

  Quaternion operator +(const Quaternion q) =>
      Quaternion(x + q.x, y + q.y, z + q.z, w + q.w);

  Quaternion operator -(const Quaternion q) =>
      Quaternion(x - q.x, y - q.y, z - q.z, w - q.w);

  Quaternion operator *(const Quaternion q) =>
      Quaternion(
        x * q.x - y * q.y - z * q.z - w * q.w,
        y * q.x + x * q.y - z * q.w - w * q.z,
        z * q.x + w * q.y - x * q.z - y * q.w,
        x * q.w + y * q.z + z * q.x + w * q.y,
      );

  Quaternion operator ^(const int n) => n == 0
      ? this
      : n == 1
          ? operator *(const Quaternion.unit())
          : n == 2
              ? operator * (const Quaternion.unit()) * operator *(const Quaternion.unit())
              : n == 3
                  ? operator * (const Quaternion.unit()) * operator * (const Quaternion.unit()) * operator *(const Quaternion.unit())
                  : throw ArgumentError('Cannot invert zero quaternion');

  Quaternion conjugate() =>
      Quaternion(x, y, z, -w);

  double norm() => (x * x + y * y + z * z + w * w) ** 0.5;

  bool get isZero => x == 0 && y == 0 && z == 0 && w == 0;

  bool get isUnit => x == 1 && y == 1 && z == 1 && w == 1;

  bool get isUnitZ => z == 1 && w == 0;

  bool get isImaginary => x == 0 && y == 0 && z == 0 && w != 0;

  bool get isPure => x == 0 && y == 0 && z == 0 && w != 0;

  Quaternion normalized() =>
      this / norm();

  Quaternion rotated(List<double> axis, double angle) =>
      const Quaternion.fromAxisAngle(axis, angle) * this;

  Quaternion rotatedComplex(List<double> axis, double angle) =>
      const Quaternion.fromAxisAngleComplex(axis, angle) * this;

  double dot(const Quaternion q) => x * q.x + y * q.y + z * q.z + w * q.w;

  double cross(const Quaternion q) =>
      x * q.y * z - x * q.z * y + y * q.z * z - y * q.w * x + z * q.w * y - z * q.x * y;

  double sign() => w.abs() == 1
      ? w.isEven
          ? 1
          : -1
      : w.abs() == 2
          ? w == 2
              ? 1
              : -1
          : w.abs() < 2
              ? 0
              : -1;
}

