void fn0(List<String> args) {

  if (args.length != 2) {
    print('Usage: dart modular_inverse.dart <a> <m>');
    return;
  }

  final BigInt a = BigInt.parse(args[0]);
  final BigInt m = BigInt.parse(args[1]);

  if (m < 2) {
    print('Modulus must be greater than 1.');
    return;
  }

  BigInt gcd = a;
  if (m > 1) {
    final BigInt b = m;
    while (b != 0) {
      final BigInt t = gcd % b;
      gcd = b;
      b = t;
    }
  }

  if (gcd > 1) {
    print('No modular inverse exists because gcd($a, $m) = $gcd.');
    return;
  }

  final BigInt x = BigInt.zero;
  final BigInt y = BigInt.one;

  while (m != 0) {
    final BigInt q = a ~/ m;
    final BigInt temp = m;
    m = a % m;
    a = temp;

    temp = x;
    x = y - q * x;
    y = temp;
  }

  final BigInt inverse = x % m;

  if (inverse < 0) {
    inverse += m;
  }

  print('$a ^-$m ≡ $inverse (mod $m)');
  print('$a ^-$m ≈ 1/$m ≈ 0.0172 (mod $m)');
}

