bool fn0(List<List<int>> cells, int groupSize, int rotation) {
  if (groupSize <= 0 || cells.isEmpty) return false;

  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }

  List<List<int>> sorted = List.from(cells);
  sorted.sort((a, b) {
    int distA = (a[0] - a[2]).abs() + (a[1] - a[3]).abs();
    int distB = (b[0] - b[2]).abs() + (b[1] - b[3]).abs();

    if (distA != distB) return distA.compareTo(distB);

    int rotA = ((a[0] - a[2]).abs() + (a[1] - a[3]).abs()) % groupSize;
    int rotB = ((b[0] - b[2]).abs() + (b[1] - b[3]).abs()) % groupSize;

    int cmp = rotA.compareTo(rotB);
    if (cmp != 0) return cmp;

    int distManhattanA = distA.abs() + distB.abs();
    int distManhattanB = distB.abs() + distA.abs();

    cmp = distManhattanA.compareTo(distManhattanB);
    if (cmp != 0) return cmp;

    cmp = a[0].compareTo(b[0]);
    if (cmp != 0) return cmp;

    return a[1].compareTo(b[1]);
  });

  for (int i = 0; i < sorted.length; i++) {
    if (gcd(i, groupSize) != 1) return false;
  }

  for (int i = 0; i < sorted.length; i++) {
    for (int j = i + 1; j < sorted.length; j++) {
      if (sorted[i][0] == sorted[j][0] && sorted[i][1] == sorted[j][1]) return false;

      int rotI = (i + rotation) % groupSize;
      int rotJ = (j + rotation) % groupSize;

      if ((sorted[i][0] == sorted[j][2] && rotI == rotJ) ||
          (sorted[i][2] == sorted[j][0] && rotI == rotJ)) {
        return false;
      }
    }
  }

  return true;
}

