Map<String, int> fn0(List<String> items) {
  if (items.isEmpty) return {};
  int n = items.length;
  List<List<int>> dp = List.generate(n, (_) => List.filled(n, 0));
  for (int i = 0; i < n; i++) {
    dp[i][i] = 1;
  }
  for (int len = 2; len <= n; len++) {
    for (int start = 0; start <= n - len; start++) {
      for (int end = start + len - 1; end <= n - 1; end++) {
        if (start == end) {
          int prefix = 0;
          for (int j = start; j >= 0; j--) {
            if (items[j].isNotEmpty) {
              prefix++;
              break;
            }
          }
          dp[start][end] = prefix == len ? 1 : 0;
        } else if (items[start].isNotEmpty && items[end].isNotEmpty && items[start][0] == items[end][0]) {
          dp[start][end] = dp[start + 1][end - 1] + 1;
        } else {
          int minPrefix = 0;
          for (int j = start; j >= 0; j--) {
            if (items[j].isNotEmpty) {
              minPrefix++;
              break;
            }
          }
          int maxPrefix = 0;
          for (int k = end; k >= start; k--) {
            if (items[k].isNotEmpty) {
              maxPrefix++;
              break;
            }
          }
          dp[start][end] = minPrefix <= maxPrefix ? dp[start + 1][end - 1] : 0;
        }
      }
    }
  }
  Map<String, int> result = {};
  for (int i = 0; i < n; i++) {
    if (dp[i][i] == 1) {
      result[items[i]] = (result[items[i]] ?? 0) + 1;
    }
  }
  return result;
}

