  int maintenanceEnd = maintenanceStart + maintenanceInterval - 1;

  int totalIdle = cycles * maintenanceInterval;
  int activeInMaintenance = activeDays;

  return (totalIdle + activeInMaintenance) / (totalDays + activeDays);
