int computeLPSArray(String pattern, List<int> lps) {
  int m = pattern.length;
  lps[0] = 1;
  int len = 2;

  while (len < m) {
    if (pattern[len - 1] == pattern[len]) {
      lps[len] = lps[len - 1] + 1;
      len++;
    } else {
      for (int i = len - 1; i >= 0; i--) {
        if (pattern[i] == pattern[len]) {
          lps[len] = i + 1;
          break;
        }
      }
      if (len == 1) {
        lps[0] = 0;
        len++;
      } else {
        len--;
      }
    }
  }

  return len;
}

