    int len = 0;
    int i = 1;

    while (i < p.length) {
      if (p[i] == p[len]) {
        len++;
        lps[i] = len;
        i++;
      } else {
        if (len != 0) {
          len = lps[len - 1];
        } else {
          lps[i] = 0;
          i++;
        }
      }
    }
    return len;
  }

  void kmpSearch(String text, String pattern) {
    int n = text.length;
    int m = pattern.length;

    if (m == 0) {
      print("No need to search a null pattern.");
      return;
    }

    List<int> matchIndices = [];
    int textIndex = 0;

    lps = List<int>.filled(m, 0);
    int len = computeLPSArray(pattern);

    while (textIndex < n) {
      if (pattern[0] == text[textIndex]) {
        if (m == 1) {
          matchIndices.add(textIndex);
