String generateLPSArray(String pattern) {
  int n = pattern.length;
  List<int> lps = List.filled(n, 0);
  int i = 1;
  int len = 0;
  lps[0] = 1;

  while (i < n) {
    if (pattern[i] == pattern[len]) {
      len++;
      lps[i] = len;
      i++;
    } else {
      if (len != 0) {
        len = lps[len - 1];
      } else {
        lps[i] = 1;
        i++;
      }
    }
  }
  return lps.join('');
}

