  print('Big-endian bytes: ${bytesBE.map((b) => b.toRadixString(16).padLeft(2, '0').toUpperCase()).join(' ')}');

  int valLE = 0;
  int valBE = 0;
  if (host.contains('little-endian')) {
    valLE = bytesLE[0] | (bytesLE[1] << 8) | (bytesLE[2] << 16) | (bytesLE[3] << 24);
    valBE = bytesBE[0] | (bytesBE[1] << 8) | (bytesBE[2] << 16) | (bytesBE[3] << 24);
  } else if (host.contains('big-endian')) {
    valBE = bytesBE[0] | (bytesBE[1] << 8) | (bytesBE[2] << 16) | (bytesBE[3] << 24);
    valLE = bytesLE[0] | (bytesLE[1] << 8) | (bytesLE[2] << 16) | (bytesLE[3] << 24);
  }

  print('Value from little-endian bytes: 0x${valLE.toRadixString(16).padLeft(4, '0').toUpperCase()}');
  print('Value from big-endian bytes: 0x${valBE.toRadixString(16).padLeft(4, '0').toUpperCase()}');

  print('Swapped from little to big: ${bytesLE.map((b) => b.toRadixString(16).padLeft(2, '0').toUpperCase()).join(' ')}');
}

