  if (cols == 0) return [];

  List<int> waitTimes = List.filled(rows, 0);

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (requestGrid[r][c] > 0) {
        waitTimes[r] = r;
        break;
      }
    }
  }

  for (int t = 0; t < waitTimes.length; t++) {
    if (waitTimes[t] == 0) continue;

    int end = waitTimes[t] + maxWait;
    for (int r = 0; r < rows; r++) {
      if (waitTimes[r] >= end) break;
      for (int c = 0; c < cols; c++) {
        if (requestGrid[r][c] == t) {
          waitTimes[r] = end;
          break;
        }
      }
    }
  }

  return waitTimes;
}

