  };

  Map<String, String> currentRole = {};

  void grantPermission(String roleName, String resource, List<String> action) {
    String resourceName = resource.split('@')[0];
    String resourceType = resource.split('@')[1];

    if (!resourceAccess.containsKey(resourceType)) {
      print('  ⚠️ Resource not found: $resourceType');
      return;
    }

    Map<String, List<String>> actions = resourceAccess[resourceType]!;

    if (!actions.containsKey(roleName)) {
      actions[roleName] = [];
    }

    actions[roleName]!.addAll(action);

    if (actions[roleName]!.length > 1) {
      currentRole[roleName] = roleName;
    }
  }

  void denyPermission(String roleName, String resource, List<String> action) {
    String resourceName = resource.split('@')[0];
    String resourceType = resource.split('@')[1];

    if (!resourceAccess.containsKey(resourceType)) {
      print('  ⚠️ Resource not found: $resourceType');
      return;
    }

    Map<String, List<String>> actions = resourceAccess[resourceType]!;

    if (!actions.containsKey(roleName)) {
      actions[roleName] = [];
    }

    actions[roleName]!.removeWhere((a) => a == action[0]);

    if (actions[roleName]!.isEmpty) {
      currentRole.remove(roleName);
    }
  }

  void assignRole(String user, String roleName) {
    if (roles.containsKey(user)) {
