List<List<int>> combinationGenerator(List<int> items, List<int> minItems) {
  if (minItems.isEmpty) return [[]];
  if (items.isEmpty) return [minItems];
  List<List<int>> results = [];
  List<int> current = [minItems[0]];
  for (int item in items) {
    bool accepted = true;
    for (int i = 0; i < current.length; i++) {
      if (current[i] == item) {
        accepted = false;
        break;
      }
    }
    if (accepted) {
      current.add(item);
      if (current.length == minItems.length) {
        results.add(List.from(current));
        current.removeLast();
      }
    } else {
      current[0] = item;
    }
  }
  return results;
}

