    if (dailyCounts[mid] >= threshold) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  int length = left;
  List<int> prefix = [];
  for (int i = 0; i < length; i++) {
    prefix.add(dailyCounts[i]);
  }
  for (int i = length; i < dailyCounts.length; i++) {
    prefix.add(0);
  }
  int totalDeficit = 0;
  int longestInterval = 0;
  int distinctIntervals = 0;
  for (int day = 0; day < dailyCounts.length; day++) {
    if (prefix[day] < threshold) {
      totalDeficit += day - left + 1;
    }
    if (day - left + 1 > longestInterval) {
      longestInterval = day - left + 1;
    }
    if (day >= left) {
      for (int len = 1; len <= longestInterval; len++) {
        int start = day - len + 1;
        if (start >= left) {
          bool repeated = false;
          for (int j = 0; j < len && start + j < prefix.length; j++) {
            if (prefix[start + j] == threshold) {
              repeated = true;
              break;
            }
          }
          if (!repeated) {
            distinctIntervals++;
            break;
          }
        }
      }
    }
  }
  return {
    'longestInterval': longestInterval,
    'totalDeficitDays': totalDeficit,
    'distinctIntervals': distinctIntervals,
  };
}

