class Rectangle {
  final double width;
  final double height;
  final double centerX;
  final double centerY;

  const Rectangle(this.width, this.height);

  const Rectangle.origin() : this(0, 0);
  const Rectangle.unit() : this(1, 1);
  const Rectangle.unitX() : this(1, 0);
  const Rectangle.unitY() : this(0, 1);
  const Rectangle.originY() : this(0, 1);
  const Rectangle.originX() : this(1, 0);

  Rectangle.originY() : this(1, 1);

  Rectangle(this.width, this.height, [this.centerX = 0, this.centerY = 0]);

  Rectangle.originY(this.width, this.height) : this(this.width, this.height, 0, 1);

  Rectangle.unitY(this.width, this.height) : this(this.width, this.height, 0, 1);

  Rectangle.unitX(this.width, this.height) : this(this.width, this.height, 1, 0);

  bool contains(Point p) {
    if (width <= 0 || height <= 0) return false;
    return (p.x >= centerX - width / 2 && p.x <= centerX + width / 2) &&
        (p.y >= centerY - height / 2 && p.y <= centerY + height / 2);
  }

  bool overlaps(Rectangle other) {
    if (width <= 0 || height <= 0 || other.width <= 0 || other.height <= 0) return false;
    double left = centerX - width / 2 < other.centerX - other.width / 2
        ? centerX - width / 2
        : other.centerX - other.width / 2;
    double right = centerX + width / 2 > other.centerX + other.width / 2
        ? centerX + width / 2
        : other.centerX + other.width / 2;
    double bottom = centerY - height / 2 < other.centerY - other.height / 2
        ? centerY - height / 2
        : other.centerY - other.height / 2;
    double top = centerY + height / 2 > other.centerY + other.height / 2
        ? centerY + height / 2
        : other.centerY + other.height / 2;
    return left < right && bottom < top;
  }

  bool equals(Rectangle other) {
    if (width != other.width || height != other.height) return false;
    if (centerX != other.centerX || centerY != other.centerY) return false;
    return true;
  }

  @override
  String toString() {
    return 'Rectangle(center: (${centerX}, ${centerY}), '
        'halfWidth: $width, halfHeight: $height)';
  }
}

