    [2.0, 2.0],
    [3.5, 5.0],
    [1.0, 1.5],
    [7.0, 0.0],
    [5.0, 1.5],
  ];

  int k = 3;
  double eps = 0.5;
  int maxIterations = 50;

  final int n = points.length;

  List<int> assignments = List.filled(n, -1);

  int find(int i) {
    if (assignments[i] == -1) {
      assignments[i] = i;
    }
    return assignments[i];
  }

  void cluster(int idx, List<int> points, int clusterSize, int clusterCenter) {
    assignments[idx] = clusterCenter;

    for (int i = 0; i < points.length; i++) {
      if (i != idx) {
        double dist = (points[i][0] - points[idx][0]).abs() +
            (points[i][1] - points[idx][1]).abs();
        if (dist <= eps) {
          int newCluster = find(i);
          clusterSize--;
          assignments[newCluster] = clusterCenter;
        }
      }
    }
  }

  bool isConverged() {
    for (int i = 0; i < n; i++) {
      if (find(i) != i) return false;
    }
    return true;
  }

  for (int iter = 0; iter < maxIterations && !isConverged(); iter++) {

    List<int> currentCenters = List.generate(k, (_) => rand.nextInt(n));

    Set<int> indices = {};
    for (int i = 0; i < n; i++) {
      indices.add(i);
    }

    while (indices.isNotEmpty) {
      int idx = indices.removeAt(0);
      cluster(idx, points, k, currentCenters[find(idx)]);
    }

    List<List<int>> clusters = List.generate(k, (_) => <int>[]);
    for (int i = 0; i < n; i++) {
      clusters[find(i)].add(i);
    }

    for (int c = 0; c < k; c++) {
      if (clusters[c].isEmpty) {
        currentCenters[c] = rand.nextInt(n);
      } else {
        double sumX = 0, sumY = 0;
        for (int point in clusters[c]) {
          sumX += points[point][0];
          sumY += points[point][1];
        }
        currentCenters[c] = [sumX / clusters[c].length, sumY / clusters[c].length];
      }
    }
  }

  print('Converged in $iter iteration(s).');
  print('Cluster ${currentCenters[0][0]}, ${currentCenters[0][1]} centroid: ${currentCenters[0]}');
  for (int c = 1; c < k; c++) {
    print('Cluster ${currentCenters[c][0]}, ${currentCenters[c][1]} centroid: ${currentCenters[c]}');
  }
  print('  Points: ${List.generate(k, (c) => clusters[c])}');
}

