    bool converged = false;
    while (step < 100 && !converged) {

      int idx = rand.nextInt(numPoints);
      int pi0 = points[idx][0], pi1 = points[idx][1];
      double d = pi0 * pi0 + pi1 * pi1;
      double dist = sqrt(d);

      bool insert = true;
      for (int j = 0; j < clusters.length; j++) {
        if (dist < clusters[j].length) {
          insert = false;
          break;
        }
      }

      if (insert) {

        clusters[0].add(idx);

        for (int k = 1; k < clusters.length; k++) {
          double dk0 = points[idx][0], dk1 = points[idx][1];
          double dK = dk0 * dk0 + dk1 * dk1;
          double D = sqrt(dK);

          if (D < clusters[k].length) {

            clusters[k].add(idx);

            for (int m = 1; m < clusters.length; m++) {
              if (m == k || m == 0) continue;
              double overlap0 = points[idx][0], overlap1 = points[idx][1];
              double overlapD = overlap0 * overlap0 + overlap1 * overlap1;
              double overlapSqrt = sqrt(overlapD);
              double distanceBetweenCentroids = sqrt(overlapD);
              if (overlapSqrt < clusters[m].length && distanceBetweenCentroids > clusters[m].length) {

                clusters[m].add(idx);
              }
            }
          }
        }
        step++;
      } else {
        for (int k = 0; k < clusters.length; k++) {
          if (clusters[k].contains(idx)) {
            clusters[k].remove(idx);
            break;
          }
        }
      }

      bool allTheSame = true;
      for (int j = 1; j < clusters.length; j++) {
        if (clusters[j].length != clusters[0].length) {
          allTheSame = false;
          break;
        }
        for (int i = 0; i < clusters[j].length; i++) {
          if (clusters[j][i] != clusters[0][i]) {
            allTheSame = false;
            break;
          }
        }
        if (!allTheSame) break;
      }
      converged = allTheSame;
    }
    print('Cluster $k: centroids: ${clusters[k].map((p) => points[p]).toList()}  Points: ${clusters[k]}');
  }

  print('Converged in $step iteration(s).');
}

